export function makeQueue(people) {
  return {
    people,
    index: 0,
    [Symbol.iterator]() {
      this.index = 0;
      return this;
    },
    next() {
      if (this.index === this.people.length) return { value: undefined, done: true };
      return { value: this.people[this.index++], done: false };
    },
  };
}
